import std.concurrent as conc
import std.io

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let ch: conc.Channel<Int64> = conc.channel(4)
    ch.send(7)
    let _ = ch.close()
    let a = ch.receive()
    let b = ch.receive()
    match a {
        Some(x) => {
            if x == 7 {
                io.println("seven")
            } else {
                io.println("ax")
            }
        }
        None => { io.println("anone") }
    }
    match b {
        Some(_) => { io.println("bsome") }
        None => { io.println("bnone") }
    }
    return Ok(())
}
